css:
        .about-container {
            font-family: inherit;
            line-height: 1.6;
            color: inherit;
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .hero-section {
            text-align: center;
            padding: 60px 0;
            background: linear-gradient(135deg, rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.4)), url('/images/gallery-darren-photographer-about/Ireland-Winter-Collage-panoramic-ireland.jpg');
            background-size: cover;
            background-position: center;
            background-attachment: fixed;
            border-radius: 12px;
            margin-bottom: 60px;
            position: relative;
        }

        .hero-section::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.3);
            border-radius: 12px;
        }

        .hero-section > * {
            position: relative;
            z-index: 2;
        }

        .hero-image {
            width: 200px;
            height: 200px;
            border-radius: 50%;
            object-fit: cover;
            margin: 0 auto 30px;
            display: block;
            border: 5px solid rgba(40, 80, 60, 0.2);
            box-shadow: 0 8px 30px rgba(0, 0, 0, 0.1);
        }

        .hero-title {
            font-size: 2.5rem;
            font-weight: 700;
            margin-bottom: 15px;
            color: white;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.7);
            position: relative;
        }

        .hero-title::after {
            content: '';
            position: absolute;
            bottom: -8px;
            left: 50%;
            transform: translateX(-50%);
            width: 80px;
            height: 3px;
            background: linear-gradient(135deg, rgb(52, 152, 219), rgb(41, 128, 185));
            border-radius: 2px;
        }

        .hero-subtitle {
            font-size: 1.3rem;
            color: rgba(255, 255, 255, 0.9);
            font-weight: 300;
            margin-bottom: 0;
            text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.6);
        }

        .hero-subtitle {
            font-size: 1.3rem;
            opacity: 0.8;
            font-weight: 300;
            margin-bottom: 0;
        }

        .content-section {
            margin-bottom: 80px;
        }

        .section-title {
            font-size: 2rem;
            font-weight: 600;
            margin-bottom: 30px;
            color: inherit;
            border-bottom: 3px solid rgb(52, 152, 219);
            padding-bottom: 10px;
            display: inline-block;
        }

        .text-image-row {
            display: flex;
            align-items: center;
            gap: 50px;
            margin-bottom: 50px;
        }

        .text-image-row.reverse {
            flex-direction: row-reverse;
        }

        .text-content {
            flex: 1;
            font-size: 1.1rem;
        }

        .image-content {
            flex: 0 0 350px;
        }

        /* Wider image content for concert photos three-column layout */
        .concert-photos-container .image-content {
            flex: 0 0 550px;
        }

        .content-image {
            width: 100%;
            height: 280px;
            object-fit: cover;
            border-radius: 12px;
            box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .content-image:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
        }

        .image-caption {
            text-align: center;
            font-style: italic;
            font-size: 0.9rem;
            opacity: 0.7;
            margin-top: 10px;
        }

        .full-width-text {
            font-size: 1.1rem;
            margin-bottom: 40px;
        }

        .intro-text {
            font-size: 1.3rem;
            line-height: 1.7;
            margin-bottom: 50px;
            text-align: center;
            color: #2c3e50;
            font-weight: 400;
            padding: 30px;
            background: linear-gradient(135deg, rgba(52, 152, 219, 0.05), rgba(41, 128, 185, 0.05));
            border-radius: 12px;
            border-left: 4px solid rgb(52, 152, 219);
        }

        .highlight-box {
            background: rgba(40, 80, 60, 0.15);
            border-left: 5px solid rgba(40, 80, 60, 0.7);
            padding: 30px;
            border-radius: 8px;
            margin: 40px 0;
            font-size: 1.1rem;
            color: #2c3e50;
        }

        .image-gallery {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
            margin: 40px 0;
        }

        .instagram-screenshot-link {
            display: block;
            max-width: 600px; /* Keeps it a reasonable size on desktop */
            width: 100%;
            margin: 0 auto;
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .instagram-screenshot-link:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
        }

        .instagram-screenshot {
            width: 100%;
            height: auto;
            display: block;
        }

        /* Special layout for What I Offer section */
        .offer-layout {
            display: flex;
            gap: 30px;
            margin: 40px 0;
        }

        .offer-left {
            flex: 0 0 300px;
        }

        .offer-right {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .offer-caption {
            margin-top: 10px;
            text-align: center;
            font-style: italic;
            font-size: 0.9rem;
            opacity: 0.7;
            position: absolute;
            bottom: -40px;
            left: 0;
            right: 0;
        }

        .offer-left, .offer-right {
            position: relative;
        }

        .offer-image-tall {
            width: 100%;
            height: 400px;
            object-fit: cover;
            border-radius: 12px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .offer-image-tall.president {
            object-position: center 25%;
        }

        .offer-image-tall:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
        }

        .offer-image-wide {
            width: 100%;
            height: 190px;
            object-fit: cover;
            border-radius: 12px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .offer-image-wide:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
        }

        .offer-image-immersive {
            width: 100%;
            height: 400px;
            object-fit: cover;
            border-radius: 12px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
            object-position: center 75%;
        }

        .offer-image-immersive:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
        }

        .image-gallery.masonry {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            grid-auto-rows: 200px;
            gap: 20px;
            margin: 40px 0;
        }

        .image-gallery.masonry .gallery-item:nth-child(1) {
            grid-row: span 2;
        }

        .image-gallery.masonry .gallery-item:nth-child(2) {
            grid-row: span 1;
        }

        .image-gallery.masonry .gallery-item:nth-child(3) {
            grid-row: span 2;
        }

        .image-gallery.masonry .gallery-item:nth-child(4) {
            grid-row: span 1;
        }

        .image-gallery.masonry .gallery-item:nth-child(5) {
            grid-row: span 2;
        }

                 .image-gallery.masonry .gallery-item:nth-child(6) {
             grid-row: span 1;
         }

         .image-gallery.masonry .gallery-item:nth-child(7) {
             grid-row: span 2;
         }

        .gallery-item {
            text-align: center;
            position: relative;
            overflow: hidden;
            border-radius: 12px;
        }

        .gallery-image {
            width: 100%;
            height: 200px;
            object-fit: cover;
            border-radius: 12px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .gallery-image:hover {
            transform: translateY(-5px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
        }

        .image-gallery.masonry .gallery-image {
            height: 100%;
        }

        /* Concert photography three-column layout */
        .concert-photos {
            display: flex;
            gap: 20px;
            margin-bottom: 20px;
            width: 100%;
            min-width: 0;
        }

        .concert-photo-left,
        .concert-photo-right {
            flex: 1 1 0;
            position: relative;
            min-width: 0;
        }

        .concert-photo-middle {
            flex: 1 1 0;
            display: flex;
            flex-direction: column;
            gap: 20px;
            position: relative;
            min-width: 0;
            width: 100%;
        }

        .concert-photo-middle > div {
            width: 100%;
            min-width: 0;
        }

        .concert-photo-middle .concert-image {
            width: 100%;
            display: block;
            min-width: 0;
        }

        .concert-image {
            width: 100%;
            height: 130px;
            object-fit: cover;
            border-radius: 12px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease;
        }

        .concert-image:hover {
            transform: scale(1.05);
        }

        .concert-image-large {
            height: 280px;
            object-position: center;
        }

        /* Overlay captions for desktop */
        .overlay-caption {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            background: linear-gradient(transparent, rgba(0,0,0,0.8));
            color: white;
            padding: 20px 15px 15px 15px;
            transform: translateY(100%);
            transition: transform 0.3s ease;
            font-size: 0.9em;
        }

        .gallery-item:hover .overlay-caption {
            transform: translateY(0);
        }

        .photographer-credit {
            font-size: 0.8em;
            opacity: 0.8;
            margin-top: 5px;
            font-style: normal;
        }

        .gallery-caption-mobile {
            display: block;
            margin-top: 10px;
            font-style: italic;
            color: #666;
            font-size: 0.9em;
        }

        /* Standard caption style for content images */
        .standard-caption {
            text-align: center;
            font-style: italic;
            font-size: 0.9rem;
            opacity: 0.7;
            margin-top: 10px;
        }

        /* Credit overlay for images */
        .credit-overlay {
            position: absolute;
            bottom: 10px;
            left: 10px;
            background: rgba(0, 0, 0, 0.7);
            color: white;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.75rem;
            font-weight: 500;
            z-index: 10;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

                 .gallery-item:hover .credit-overlay,
         .image-content:hover .credit-overlay,
         .offer-left:hover .credit-overlay,
         .offer-right:hover .credit-overlay,
         .concert-photo-left:hover .credit-overlay,
         .concert-photo-right:hover .credit-overlay,
         .concert-photo-middle:hover .credit-overlay {
             opacity: 1;
         }

        .credit-overlay.mobile {
            opacity: 1;
            background: rgba(0, 0, 0, 0.8);
            font-size: 0.7rem;
            padding: 3px 6px;
            bottom: 10px;
            left: 10px;
        }

        .cta-section {
            background: linear-gradient(135deg, rgba(40, 80, 60, 0.15), rgba(80, 120, 80, 0.15));
            border-radius: 12px;
            padding: 50px 40px;
            text-align: center;
            margin-top: 60px;
            border: 2px solid rgba(40, 80, 60, 0.2);
        }

        .cta-title {
            font-size: 2rem;
            font-weight: 600;
            margin-bottom: 20px;
            color: #2c3e50;
        }

        .cta-text {
            font-size: 1.2rem;
            margin-bottom: 30px;
            color: #34495e;
            opacity: 1;
        }

        .credits-section {
            background: rgba(40, 80, 60, 0.05);
            border-top: 1px solid rgba(40, 80, 60, 0.2);
            padding: 40px 0;
            margin-top: 80px;
            font-size: 0.9rem;
            color: #666;
        }

        .credits-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .credits-title {
            font-size: 1.1rem;
            font-weight: 600;
            margin-bottom: 20px;
            color: #2c3e50;
            text-align: center;
        }

        .credits-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 20px;
        }

        .credit-item {
            background: rgba(255, 255, 255, 0.7);
            padding: 15px;
            border-radius: 8px;
            border-left: 3px solid rgba(40, 80, 60, 0.3);
        }

        .credit-photographer {
            font-weight: 600;
            color: #2c3e50;
            margin-bottom: 5px;
        }

        .credit-images {
            font-size: 0.85rem;
            line-height: 1.4;
        }

        /* Responsive Design */
        @media (max-width: 768px) {
            .about-container {
                padding: 0 15px;
            }

            .hero-section {
                padding: 40px 20px;
                background: linear-gradient(135deg, rgba(40, 80, 60, 0.05), rgba(80, 120, 80, 0.05));
                background-attachment: scroll;
            }

            .hero-section::before {
                display: none;
            }

            .hero-title {
                font-size: 2rem;
                color: inherit;
                text-shadow: none;
            }

            .hero-subtitle {
                font-size: 1.1rem;
                color: inherit;
                opacity: 0.8;
                text-shadow: none;
            }

            .text-image-row,
            .text-image-row.reverse {
                flex-direction: column;
                gap: 30px;
                text-align: center;
            }

            .image-content {
                flex: none;
                max-width: 100%;
            }

            .content-image {
                height: 250px;
            }

            .section-title {
                font-size: 1.7rem;
            }

                         .content-section {
                 margin-bottom: 60px;
             }

             .intro-text {
                 font-size: 1.2rem;
                 padding: 25px 20px;
                 margin-bottom: 40px;
             }

            .cta-section {
                padding: 40px 25px;
            }

            .cta-title {
                font-size: 1.7rem;
            }

            .image-gallery {
                grid-template-columns: 1fr;
                gap: 20px;
            }

            .offer-layout {
                flex-direction: column;
                gap: 20px;
            }

            .offer-left {
                flex: none;
            }

            .offer-image-tall {
                height: 300px;
            }

            .offer-image-wide {
                height: 200px;
            }

            .offer-image-immersive {
                height: 300px;
            }

            .image-gallery.masonry {
                grid-template-columns: 1fr;
                grid-auto-rows: 200px;
            }

                         .image-gallery.masonry .gallery-item:nth-child(n) {
                 grid-row: span 1;
             }

                           /* Make Ingebjørg photo taller on mobile */
              .image-gallery.masonry .gallery-item:nth-child(5) .gallery-image {
                  height: 300px !important;
              }

              /* Make the last image (7th item) as tall as Ingebjørg image on mobile */
              .image-gallery.masonry .gallery-item:nth-child(7) .gallery-image {
                  height: 300px !important;
              }

            .concert-photos {
                flex-direction: column;
            }

            .concert-photo-middle {
                flex-direction: column;
            }

            .concert-image {
                height: 150px;
            }

            .concert-image-large {
                height: 200px;
            }

            /* Make Alex Skolnick image taller on mobile only */
            .concert-photo-left .concert-image-large {
                height: 250px !important;
                object-position: center top !important;
            }

            .gallery-caption-mobile {
                display: block;
            }

                         .overlay-caption {
                 display: none;
             }

             .credit-overlay {
                 opacity: 1;
                 background: rgba(0, 0, 0, 0.8);
                 font-size: 0.7rem;
                 padding: 3px 6px;
                 bottom: 10px;
                 left: 10px;
             }

                           /* Hide caption for Olympia box photo on mobile */
              .concert-photo-left div:nth-child(2) + p {
                  display: none;
              }

              /* Mobile caption positioning for Ingebjørg photo */
              .image-gallery.masonry .gallery-item:nth-child(5) p {
                  position: absolute;
                  bottom: -40px;
                  left: 0;
                  right: 0;
                  text-align: center;
                  font-size: 0.85rem;
              }

              /* Mobile viewpoint adjustment for David K image */
              .offer-left .offer-image-tall {
                  object-position: center 30%;
              }
        }

        @media (min-width: 769px) {
            .gallery-caption-mobile {
                display: none;
            }

            .overlay-caption {
                display: block;
            }
        }

                 @media (max-width: 480px) {
             .hero-image {
                 width: 150px;
                 height: 150px;
             }
 
             .hero-title {
                 font-size: 1.8rem;
             }
 
             .section-title {
                 font-size: 1.5rem;
             }
 
             .concert-photo-left {
                 flex-direction: column;
             }
         }

         /* Fix for menu breakpoint between 1199px and 992px */
         @media (max-width: 1199px) and (min-width: 992px) {
             .about-container {
                 padding: 0 15px;
             }
             
             /* Add any specific menu fixes here if needed */
             .hero-title {
                 font-size: 2.2rem;
             }
             
             .hero-subtitle {
                 font-size: 1.2rem;
             }
         }
        .thank-you-section {
            text-align: center;
            padding: 60px 0;
            margin-top: 40px;
            background: linear-gradient(135deg, rgba(40, 80, 60, 0.08), rgba(80, 120, 80, 0.08));
            border-radius: 12px;
            border: 2px solid rgba(40, 80, 60, 0.15);
        }

        .thank-you-section h3,
        .thank-you-section p {
            text-align: center;
            margin-left: auto !important;
            margin-right: auto !important;
            max-width: 42rem;
        }
        .intro-text p,
        .hero-subtitle,
        .cta-section p {
            margin-left: auto;
            margin-right: auto;
            text-align: center;
            max-width: none;
        }

        .thank-you-section {
            width: 100%;
            box-sizing: border-box;
        }
        .thank-you-closing {
            font-size: 1rem;
            color: #666;
            font-style: italic;
            margin: 0 auto !important;
            text-align: center;
            max-width: 42rem;
        }
